import{_ as s,o as a,c as e,ag as p}from"./chunks/framework.DEqXEGcv.js";const m=JSON.parse('{"title":"API Audit Prompt — Swarm Framework","description":"","frontmatter":{},"headers":[],"relativePath":"prompts/api-audit.md","filePath":"prompts/api-audit.md","lastUpdated":1772637980000}'),t={name:"prompts/api-audit.md"};function i(o,n,l,r,c,d){return a(),e("div",null,[...n[0]||(n[0]=[p(`<h1 id="api-audit-prompt-—-swarm-framework" tabindex="-1">API Audit Prompt — Swarm Framework <a class="header-anchor" href="#api-audit-prompt-—-swarm-framework" aria-label="Permalink to &quot;API Audit Prompt — Swarm Framework&quot;">​</a></h1><p>Use this prompt to run a structured audit of the Swarm public API surface. It produces a ranked findings table graded on two axes: impact for human developers and impact for coding agents (LLMs writing Swarm code).</p><hr><h2 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;role&gt;</span></span>
<span class="line"><span>You are a principal Swift 6.2 API designer with deep expertise in framework ergonomics for two audiences:</span></span>
<span class="line"><span>1. Human developers building AI applications on Apple platforms.</span></span>
<span class="line"><span>2. Coding agents (LLMs like Claude, GPT, Gemini) that write, extend, and debug Swarm code autonomously.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your goal is to audit the Swarm framework&#39;s public API and produce a prioritized list of issues and improvements, each graded by impact on both audiences.</span></span>
<span class="line"><span>&lt;/role&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;context&gt;</span></span>
<span class="line"><span>## What Swarm is</span></span>
<span class="line"><span>Swarm is a Swift 6.2 multi-agent orchestration framework for Apple platforms and Linux. It provides:</span></span>
<span class="line"><span>- \`AgentRuntime\` protocol — the central abstraction every agent conforms to</span></span>
<span class="line"><span>- \`Agent\` actor — the primary concrete agent type (tool-calling via LLMs)</span></span>
<span class="line"><span>- \`Workflow\` struct — fluent multi-agent pipeline composition</span></span>
<span class="line"><span>- \`Conversation\` class — high-level multi-turn interface</span></span>
<span class="line"><span>- \`@Tool\` / \`@Parameter\` / \`@AgentActor\` macros — zero-boilerplate tool and agent definition</span></span>
<span class="line"><span>- Memory, Guardrails, Handoffs, Observability, Resilience subsystems</span></span>
<span class="line"><span>- MCP integration (as client and server)</span></span>
<span class="line"><span>- HiveCore DAG runtime bridge</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Source files to read</span></span>
<span class="line"><span>Read these files to ground your analysis in the actual implementation:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Core protocol and types:</span></span>
<span class="line"><span>- Sources/Swarm/Core/AgentRuntime.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/AnyAgent.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/Conversation.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/Environment.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/AgentEnvironment.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/ObservedAgent.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/RunHooks.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/EventStreamHooks.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/StreamOperations.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Agent implementation and builder:</span></span>
<span class="line"><span>- Sources/Swarm/Agents/Agent.swift</span></span>
<span class="line"><span>- Sources/Swarm/Agents/AgentBuilder.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Workflow and handoff:</span></span>
<span class="line"><span>- Sources/Swarm/Workflow/Workflow.swift</span></span>
<span class="line"><span>- Sources/Swarm/Workflow/Workflow+Durable.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/Handoff/Handoff.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/Handoff/HandoffConfiguration.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/Handoff/HandoffOptions.swift</span></span>
<span class="line"><span>- Sources/Swarm/Core/Handoff/HandoffBuilder.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tools:</span></span>
<span class="line"><span>- Sources/Swarm/Tools/Tool.swift</span></span>
<span class="line"><span>- Sources/Swarm/Tools/AgentTool.swift</span></span>
<span class="line"><span>- Sources/Swarm/Tools/BuiltInTools.swift</span></span>
<span class="line"><span>- Sources/Swarm/Tools/ToolCallGoal.swift</span></span>
<span class="line"><span>- Sources/Swarm/Tools/ToolExecutionEngine.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Memory and sessions:</span></span>
<span class="line"><span>- Sources/Swarm/Memory/MemorySessionLifecycle.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Macros:</span></span>
<span class="line"><span>- Sources/Swarm/Macros/MacroDeclarations.swift</span></span>
<span class="line"><span>- Sources/SwarmMacros/AgentMacro.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Guardrails:</span></span>
<span class="line"><span>- Sources/Swarm/Guardrails/GuardrailRunner.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Observability:</span></span>
<span class="line"><span>- Sources/Swarm/Observability/TracingHelper.swift</span></span>
<span class="line"><span>- Sources/Swarm/Observability/SwiftLogTracer.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Providers:</span></span>
<span class="line"><span>- Sources/Swarm/Providers/Conduit/ConduitProviderSelection.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HiveSwarm:</span></span>
<span class="line"><span>- Sources/Swarm/HiveSwarm/RetryPolicyBridge.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MCP:</span></span>
<span class="line"><span>- Sources/SwarmMCP/SwarmMCPErrorMapper.swift</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reference docs (read these for design intent before reading source):</span></span>
<span class="line"><span>- docs/reference/front-facing-api.md       ← canonical design spec</span></span>
<span class="line"><span>- docs/reference/api-catalog.md            ← full type catalog with signatures</span></span>
<span class="line"><span>- docs/plans/2026-03-02-swarm-api-redesign.md ← locked design decisions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Grading rubric</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Score each finding on two axes, 1–5:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Human developer score (H)** — how much this affects a Swift developer writing Swarm-powered apps:</span></span>
<span class="line"><span>- 5: Blocks or confuses all users; misuse is the default</span></span>
<span class="line"><span>- 4: Causes regular confusion; workaround exists but isn&#39;t obvious</span></span>
<span class="line"><span>- 3: Causes occasional confusion; easy to work around once known</span></span>
<span class="line"><span>- 2: Minor friction; most developers adapt quickly</span></span>
<span class="line"><span>- 1: Edge case; rarely encountered</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Coding agent score (A)** — how much this affects an LLM writing or debugging Swarm code:</span></span>
<span class="line"><span>- 5: Causes the agent to generate incorrect or ambiguous code nearly every time</span></span>
<span class="line"><span>- 4: Causes frequent wrong-first-attempts; agent corrects after feedback</span></span>
<span class="line"><span>- 3: Causes plausible-but-wrong first attempt in non-trivial scenarios</span></span>
<span class="line"><span>- 2: Occasionally misleads; agent self-corrects from context</span></span>
<span class="line"><span>- 1: Rarely encountered; agent handles via pattern matching</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Impact = H + A** (max 10). Sort findings descending by Impact.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Categories to investigate</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Work through each category in order. For each, read the relevant source files before forming opinions.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **Naming consistency** — Do type names, parameter labels, and DSL component names follow a single coherent convention? Look for cases where the same concept has different names in different parts of the API (e.g., \`Memory\` protocol vs \`AgentMemoryComponent\` DSL type).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. **Construction path ambiguity** — How many ways can you construct the same thing? For each major type, count the construction paths (memberwise init, builder, DSL, factory function). Flag cases where 3+ paths exist without a documented &quot;preferred&quot; path.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. **Behavioral consistency** — Do methods with similar names behave the same way across types? Specifically check:</span></span>
<span class="line"><span>   - Every \`.stream()\` method: what does it return? (\`AsyncThrowingStream&lt;AgentEvent, Error&gt;\` vs \`String\`)</span></span>
<span class="line"><span>   - Every \`.run()\` method: does it always return \`AgentResult\`?</span></span>
<span class="line"><span>   - Does \`Workflow\` expose all the same capabilities as running agents directly?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. **Type safety gaps** — Find places where the API falls back to \`String\`-keyed or \`Any\`-based patterns instead of typed alternatives. Check \`AgentContext\`, handoff context dictionaries, metadata on results.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. **Misleading names** — Find public names whose surface meaning contradicts their implementation. Examples to verify: \`MergeStrategy.structured\` — is the output actually structured data? \`HandoffHistory\` cases — do they clearly communicate what history is included?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6. **Discovery failure points** — Identify parts of the API a developer would not find without reading docs. This includes: non-obvious entry points, buried capabilities in nested namespaces (e.g., \`Workflow.advanced\`), types that look internal but are public.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7. **Surface area excess** — Find public types or overloads that solve the same problem and could be consolidated. Focus on cases where removing one path would make the remaining path obviously correct.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>8. **Concurrency contract gaps** — Check whether every \`async\` requirement is justified, whether \`nonisolated\` is used consistently on read-only properties, and whether any \`@unchecked Sendable\` is used in public API (a red flag for API consumers).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>9. **Error completeness** — For each major subsystem, can a caller fully handle failures with the errors thrown? Look for cases where \`Error\` is thrown (not \`AgentError\` or a typed error) forcing callers to cast.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10. **Coding-agent-specific traps** — Find patterns that would cause an LLM to generate plausible-but-wrong code. These include: two systems that solve the same problem (dual handoff systems), naming that matches standard Swift patterns but behaves differently, DSL components that look optional but are required for correct behavior.</span></span>
<span class="line"><span>&lt;/context&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;instructions&gt;</span></span>
<span class="line"><span>## Phase 1 — Ground yourself in the codebase</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Before forming any opinions, read the reference docs in this order:</span></span>
<span class="line"><span>1. docs/reference/front-facing-api.md (design intent and invariants)</span></span>
<span class="line"><span>2. docs/reference/api-catalog.md (full type catalog)</span></span>
<span class="line"><span>3. docs/plans/2026-03-02-swarm-api-redesign.md (locked decisions — do not flag these as issues)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Then read the source files listed in the context. For each source file:</span></span>
<span class="line"><span>- Note the public declarations (types, methods, properties)</span></span>
<span class="line"><span>- Note any inconsistencies with the design spec</span></span>
<span class="line"><span>- Note any \`@unchecked Sendable\`, stringly-typed APIs, or naming mismatches</span></span>
<span class="line"><span>- Note any inline comments that suggest instability (e.g. &quot;// Phase N&quot;, &quot;// TODO&quot;, &quot;// FIXME&quot;, &quot;// legacy&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Phase 2 — Identify findings</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Work through each of the 10 categories from the context. For each finding:</span></span>
<span class="line"><span>- State the specific type/method/file where the issue occurs</span></span>
<span class="line"><span>- Describe the expected vs actual behavior (for behavioral issues) or the expected vs actual name (for naming issues)</span></span>
<span class="line"><span>- State the concrete failure mode for a human developer</span></span>
<span class="line"><span>- State the concrete failure mode for a coding agent</span></span>
<span class="line"><span>- Assign H score and A score (1–5 each)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A &quot;finding&quot; is a specific, actionable observation. Do not report vague findings like &quot;the API is large.&quot; Report findings like: &quot;\`Conversation.stream()\` returns \`String\` instead of \`AsyncThrowingStream&lt;AgentEvent, Error&gt;\`, breaking the behavioral contract set by \`AgentRuntime.stream()\`.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Each finding must have a proposed resolution — a concrete change to the API (rename, remove, change signature, add documentation, etc.).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Phase 3 — Rank and report</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Sort all findings by Impact (H + A) descending. For ties, sort by H score descending (human impact is the tiebreaker).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Output your findings in the structured format specified below. Do not truncate — include every finding you identified.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Phase 4 — Summary</span></span>
<span class="line"><span></span></span>
<span class="line"><span>After the findings table, write a brief executive summary (max 200 words) covering:</span></span>
<span class="line"><span>- The single most important theme across the findings</span></span>
<span class="line"><span>- The three highest-leverage fixes (those that improve both H and A scores simultaneously)</span></span>
<span class="line"><span>- Any locked design decisions from the redesign plan that partially address existing findings</span></span>
<span class="line"><span>&lt;/instructions&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;output_format&gt;</span></span>
<span class="line"><span>## API Audit Findings</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| # | Finding | File | H | A | Impact | Proposed Resolution |</span></span>
<span class="line"><span>|---|---------|------|---|---|--------|-------------------|</span></span>
<span class="line"><span>| 1 | [concise finding title] | [file:line] | [1-5] | [1-5] | [H+A] | [one-line fix] |</span></span>
<span class="line"><span>| 2 | ... | | | | | |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(sort by Impact descending)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Detailed Findings</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### [#N] [Finding Title] · Impact [score]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Location**: \`TypeName.methodName\` in \`path/to/file.swift:line\`</span></span>
<span class="line"><span>**Category**: [one of the 10 categories above]</span></span>
<span class="line"><span>**Human impact (H=[score])**: [1-2 sentences describing a human developer hitting this]</span></span>
<span class="line"><span>**Agent impact (A=[score])**: [1-2 sentences describing an LLM generating wrong code because of this]</span></span>
<span class="line"><span>**Root cause**: [what in the implementation causes this]</span></span>
<span class="line"><span>**Proposed resolution**: [specific, actionable API change with example if helpful]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Executive Summary</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[max 200 words]</span></span>
<span class="line"><span>&lt;/output_format&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;examples&gt;</span></span>
<span class="line"><span>  &lt;example&gt;</span></span>
<span class="line"><span>    &lt;input&gt;</span></span>
<span class="line"><span>      You find that \`Conversation.stream(_ input: String)\` returns \`String\` while</span></span>
<span class="line"><span>      \`AgentRuntime.stream(_ input: String, ...)\` returns \`AsyncThrowingStream&lt;AgentEvent, Error&gt;\`.</span></span>
<span class="line"><span>    &lt;/input&gt;</span></span>
<span class="line"><span>    &lt;ideal_output&gt;</span></span>
<span class="line"><span>      ### [#3] \`Conversation.stream()\` breaks \`AgentRuntime.stream()\` contract · Impact 8</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      **Location**: \`Conversation.stream\` in \`Sources/Swarm/Core/Conversation.swift:57\`</span></span>
<span class="line"><span>      **Category**: Behavioral consistency</span></span>
<span class="line"><span>      **Human impact (H=4)**: A developer who learns streaming via \`AgentRuntime\` writes</span></span>
<span class="line"><span>      \`for try await event in conversation.stream(input)\` and gets a compile error because</span></span>
<span class="line"><span>      \`String\` is not an \`AsyncSequence\`. The error message does not point to the API mismatch.</span></span>
<span class="line"><span>      **Agent impact (A=4)**: An LLM that has seen \`AgentRuntime.stream()\` will generate</span></span>
<span class="line"><span>      \`for try await event in conversation.stream(input)\` — syntactically plausible, type-incorrect.</span></span>
<span class="line"><span>      The agent self-corrects only after seeing the type error.</span></span>
<span class="line"><span>      **Root cause**: \`Conversation.stream()\` was designed as a convenience that buffers the full</span></span>
<span class="line"><span>      output and returns a \`String\`, but its name matches the streaming pattern exactly.</span></span>
<span class="line"><span>      **Proposed resolution**: Rename \`Conversation.stream()\` to \`Conversation.streamToString()\`,</span></span>
<span class="line"><span>      and add a true \`Conversation.stream()\` returning \`AsyncThrowingStream&lt;AgentEvent, Error&gt;\`</span></span>
<span class="line"><span>      that delegates to the underlying agent&#39;s \`stream()\` method.</span></span>
<span class="line"><span>    &lt;/ideal_output&gt;</span></span>
<span class="line"><span>  &lt;/example&gt;</span></span>
<span class="line"><span>&lt;/examples&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;constraints&gt;</span></span>
<span class="line"><span>- Ground every finding in the actual source code. Quote file paths and line numbers.</span></span>
<span class="line"><span>- Do not flag locked design decisions from docs/plans/2026-03-02-swarm-api-redesign.md as issues.</span></span>
<span class="line"><span>- Do not invent findings. If you cannot find evidence of an issue in the source, do not report it.</span></span>
<span class="line"><span>- Distinguish between &quot;the implementation is wrong&quot; and &quot;the API design is ambiguous&quot; — both are valid findings but require different resolutions.</span></span>
<span class="line"><span>- A finding with only H&gt;3 is a human-experience issue. A finding with only A&gt;3 is an agent-experience issue. The most valuable findings are those with both H≥3 and A≥3 — these should be fixed first.</span></span>
<span class="line"><span>- Keep each proposed resolution specific enough that a developer could implement it without asking follow-up questions.</span></span>
<span class="line"><span>- If you are unsure about a finding (e.g. you cannot tell whether a behavior is intentional from reading the source), mark it [UNVERIFIED] and note what additional context would confirm or refute it.</span></span>
<span class="line"><span>&lt;/constraints&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Keep working until you have read all listed source files and produced a complete findings table and detailed section. Only stop when you are confident every source file has been examined and every finding has a concrete location reference and proposed resolution.</span></span></code></pre></div><hr><h2 id="how-to-use-this-prompt" tabindex="-1">How to use this prompt <a class="header-anchor" href="#how-to-use-this-prompt" aria-label="Permalink to &quot;How to use this prompt&quot;">​</a></h2><h3 id="as-a-claude-code-agent-task" tabindex="-1">As a Claude Code agent task <a class="header-anchor" href="#as-a-claude-code-agent-task" aria-label="Permalink to &quot;As a Claude Code agent task&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Paste directly into a claude session in the Swarm repo:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The agent will read all source files and produce the audit report.</span></span></code></pre></div><h3 id="as-a-sub-agent-prompt" tabindex="-1">As a sub-agent prompt <a class="header-anchor" href="#as-a-sub-agent-prompt" aria-label="Permalink to &quot;As a sub-agent prompt&quot;">​</a></h3><p>Invoke via the <code>Explore</code> or <code>general-purpose</code> agent with <code>subagent_type: &quot;general-purpose&quot;</code> and set <code>mode: &quot;plan&quot;</code> for review before the agent writes anything.</p><h3 id="expected-output-structure" tabindex="-1">Expected output structure <a class="header-anchor" href="#expected-output-structure" aria-label="Permalink to &quot;Expected output structure&quot;">​</a></h3><p>The prompt produces three artifacts:</p><ol><li><strong>Summary table</strong> — sortable at a glance by Impact</li><li><strong>Detailed findings</strong> — each with location, root cause, and resolution</li><li><strong>Executive summary</strong> — prioritized action list</li></ol><h3 id="scoring-reminder" tabindex="-1">Scoring reminder <a class="header-anchor" href="#scoring-reminder" aria-label="Permalink to &quot;Scoring reminder&quot;">​</a></h3><ul><li><strong>H</strong> = human developer friction (1–5)</li><li><strong>A</strong> = coding agent confusion (1–5)</li><li><strong>Impact</strong> = H + A (max 10)</li><li>Fix order: Impact ≥ 8 first, then ≥ 6, then ≤ 5 as bandwidth allows</li></ul><h3 id="what-this-prompt-does-not-do" tabindex="-1">What this prompt does NOT do <a class="header-anchor" href="#what-this-prompt-does-not-do" aria-label="Permalink to &quot;What this prompt does NOT do&quot;">​</a></h3><ul><li>It does not write fixes — it identifies them. Use a <code>swarm-implementer</code> sub-agent for that.</li><li>It does not test the API — it reads source and reasons statically. Pair with <code>swift test</code> to validate proposed resolutions.</li><li>It does not flag locked decisions from the redesign plan — those are immutable by sub-agents per AGENTS.md.</li></ul>`,18)])])}const h=s(t,[["render",i]]);export{m as __pageData,h as default};
